<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Falling Sand Sandbox</title>
<style>
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;min-height:100%}
  body{
    background:#0b0e14;color:#e8eaf0;
    font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
    display:flex;flex-direction:column;align-items:center;
    padding:24px 12px 40px;
  }
  h1{margin:0 0 6px;font-size:22px;letter-spacing:.3px}
  p.sub{margin:0 0 16px;color:#9aa3b2;font-size:13px}
  #wrap{display:flex;flex-direction:column;align-items:center;gap:14px}
  #sand{
    width:500px;height:500px;
    image-rendering:pixelated;image-rendering:crisp-edges;
    background:#05060a;border:1px solid #2a3140;border-radius:10px;
    box-shadow:0 10px 40px rgba(0,0,0,.6);
    cursor:crosshair;touch-action:none;
  }
  #controls{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:520px}
  button{
    appearance:none;border:1px solid #343c4e;background:#1a2130;color:#e8eaf0;
    padding:9px 14px;border-radius:8px;font-size:14px;cursor:pointer;
    transition:transform .05s,background .15s,border-color .15s;
  }
  button:hover{background:#232c42}
  button:active{transform:scale(.97)}
  button.active{border-color:#6ea8ff;background:#27406e;box-shadow:0 0 0 1px #6ea8ff inset}
  #clear{border-color:#7a2e35;background:#3a1519}
  #clear:hover{background:#4d1c21}
  .hint{color:#8b94a7;font-size:12px;max-width:520px;text-align:center;line-height:1.5}
</style>
</head>
<body>
<div id="wrap">
  <h1>Falling Sand Sandbox</h1>
  <p class="sub">Drag on the canvas to paint. Sand sinks, water flows, acid eats walls.</p>
  <canvas id="sand"></canvas>
  <div id="controls">
    <button id="mat-sand">Sand</button>
    <button id="mat-water">Water</button>
    <button id="mat-wall">Wall</button>
    <button id="mat-acid">Acid</button>
    <button id="mat-empty">Eraser</button>
    <button id="clear">Clear</button>
  </div>
  <div class="hint">Tip: pour sand into water — displaced liquid escapes sideways instead of shooting upward.</div>
</div>
<script>
(function(){
  var W = 100, H = 100;
  var EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
  var NAMES=["empty","sand","water","wall","acid"];
  var grid = new Uint8Array(W*H);
  var moved = new Uint8Array(W*H);

  var canvas = document.getElementById("sand");
  canvas.width = W; canvas.height = H;
  var ctx = canvas.getContext("2d");
  var img = ctx.createImageData(W,H);

  var COLORS=[
    [8,10,18,255],
    [232,193,75,255],
    [59,130,246,255],
    [148,155,168,255],
    [74,222,128,255]
  ];

  function render(){
    var d = img.data;
    for(var i=0;i<W*H;i++){
      var c=COLORS[grid[i]];
      var o=i*4;
      d[o]=c[0];d[o+1]=c[1];d[o+2]=c[2];d[o+3]=c[3];
    }
    ctx.putImageData(img,0,0);
  }

  function updateWater(x,y){
    var i=y*W+x;
    if(y+1<H){
      if(grid[(y+1)*W+x]===EMPTY){
        grid[(y+1)*W+x]=WATER;grid[i]=EMPTY;moved[(y+1)*W+x]=1;return;
      }
      var dirs=Math.random()<0.5?[-1,1]:[1,-1];
      for(var k=0;k<2;k++){
        var nx=x+dirs[k],ny=y+1;
        if(nx<0||nx>=W)continue;
        if(grid[ny*W+nx]===EMPTY){
          grid[ny*W+nx]=WATER;grid[i]=EMPTY;moved[ny*W+nx]=1;return;
        }
      }
    }
    var d2=Math.random()<0.5?[-1,1]:[1,-1];
    for(var k2=0;k2<2;k2++){
      var nx2=x+d2[k2];
      if(nx2<0||nx2>=W)continue;
      if(grid[y*W+nx2]===EMPTY){
        grid[y*W+nx2]=WATER;grid[i]=EMPTY;moved[y*W+nx2]=1;return;
      }
    }
  }

  function updateAcid(x,y){
    var i=y*W+x;
    var neigh=[[x,y+1],[x-1,y],[x+1,y]];
    for(var n=0;n<neigh.length;n++){
      var nx=neigh[n][0],ny=neigh[n][1];
      if(nx<0||nx>=W||ny<0||ny>=H)continue;
      var t=grid[ny*W+nx];
      if(t===SAND||t===WALL){
        if(Math.random()<0.28){
          grid[ny*W+nx]=EMPTY;
          if(Math.random()<0.30){
            grid[i]=EMPTY;
            return;
          }
        }
      }
    }
    if(grid[i]!==ACID)return;
    if(y+1<H){
      if(grid[(y+1)*W+x]===EMPTY){
        grid[(y+1)*W+x]=ACID;grid[i]=EMPTY;moved[(y+1)*W+x]=1;return;
      }
      var dirs=Math.random()<0.5?[-1,1]:[1,-1];
      for(var k=0;k<2;k++){
        var dx=dirs[k],nx2=x+dx,ny2=y+1;
        if(nx2<0||nx2>=W)continue;
        if(grid[ny2*W+nx2]===EMPTY){
          grid[ny2*W+nx2]=ACID;grid[i]=EMPTY;moved[ny2*W+nx2]=1;return;
        }
      }
    }
    var d2=Math.random()<0.5?[-1,1]:[1,-1];
    for(var k2=0;k2<2;k2++){
      var nx3=x+d2[k2];
      if(nx3<0||nx3>=W)continue;
      if(grid[y*W+nx3]===EMPTY){
        grid[y*W+nx3]=ACID;grid[i]=EMPTY;moved[y*W+nx3]=1;return;
      }
    }
  }

  function updateSand(x,y){
    var i=y*W+x;
    if(y+1>=H)return;
    var below=grid[(y+1)*W+x];
    if(below===EMPTY){
      grid[(y+1)*W+x]=SAND;grid[i]=EMPTY;moved[(y+1)*W+x]=1;return;
    }
    if(below===WATER||below===ACID){
      var aboveIsSand=(y>0&&grid[(y-1)*W+x]===SAND);
      if(!aboveIsSand){
        grid[i]=below;grid[(y+1)*W+x]=SAND;
        moved[i]=1;moved[(y+1)*W+x]=1;return;
      }else{
        var dirs=Math.random()<0.5?[-1,1]:[1,-1];
        var disp=below;
        for(var d=0;d<2;d++){
          var dx=dirs[d];
          var cands=[[x+dx,y],[x+dx,y+1]];
          for(var c=0;c<2;c++){
            var tx=cands[c][0],ty=cands[c][1];
            if(tx<0||tx>=W||ty<0||ty>=H)continue;
            if(grid[ty*W+tx]===EMPTY){
              grid[ty*W+tx]=disp;
              grid[(y+1)*W+x]=SAND;
              grid[i]=EMPTY;
              moved[(y+1)*W+x]=1;
              moved[ty*W+tx]=1;
              return;
            }
          }
        }
        var left=(x-1>=0)?grid[y*W+x-1]:WALL;
        var right=(x+1<W)?grid[y*W+x+1]:WALL;
        if(left===WATER||left===ACID||right===WATER||right===ACID){
          grid[i]=disp;grid[(y+1)*W+x]=SAND;
          moved[i]=1;moved[(y+1)*W+x]=1;return;
        }
      }
    }
    var dirs2=Math.random()<0.5?[-1,1]:[1,-1];
    var above2=(y>0&&grid[(y-1)*W+x]===SAND);
    for(var k=0;k<2;k++){
      var nx=x+dirs2[k],ny=y+1;
      if(nx<0||nx>=W||ny>=H)continue;
      var t=grid[ny*W+nx];
      if(t===EMPTY){
        grid[ny*W+nx]=SAND;grid[i]=EMPTY;moved[ny*W+nx]=1;return;
      }
      if((t===WATER||t===ACID)&&!above2){
        grid[i]=t;grid[ny*W+nx]=SAND;
        moved[i]=1;moved[ny*W+nx]=1;return;
      }
    }
  }

  function step(){
    moved.fill(0);
    for(var y=H-1;y>=0;y--){
      var ltr=Math.random()<0.5;
      for(var xi=0;xi<W;xi++){
        var x=ltr?xi:(W-1-xi);
        var i=y*W+x;
        if(moved[i])continue;
        var c=grid[i];
        if(c===EMPTY||c===WALL)continue;
        if(c===SAND)updateSand(x,y);
        else if(c===WATER)updateWater(x,y);
        else if(c===ACID)updateAcid(x,y);
      }
    }
  }

  function nameToId(n){
    if(n==="empty")return EMPTY;
    if(n==="sand")return SAND;
    if(n==="water")return WATER;
    if(n==="wall")return WALL;
    if(n==="acid")return ACID;
    return -1;
  }

  window.sim={
    w:W,h:H,
    tick:function(n){
      n=(n===undefined)?1:(n|0);
      for(var k=0;k<n;k++)step();
      render();
    },
    get:function(x,y){
      if(x<0||x>=W||y<0||y>=H)return "wall";
      return NAMES[grid[y*W+x]];
    },
    set:function(x,y,m){
      if(x<0||x>=W||y<0||y>=H)return;
      var id=nameToId(m);
      if(id<0)return;
      grid[y*W+x]=id;
      render();
    },
    clear:function(){
      grid.fill(EMPTY);
      render();
    }
  };

  var current="sand";
  var btns={sand:document.getElementById("mat-sand"),water:document.getElementById("mat-water"),wall:document.getElementById("mat-wall"),acid:document.getElementById("mat-acid"),empty:document.getElementById("mat-empty")};
  function refreshActive(){
    for(var k in btns){if(btns.hasOwnProperty(k))btns[k].classList.toggle("active",k===current);}
  }
  btns.sand.addEventListener("click",function(){current="sand";refreshActive();});
  btns.water.addEventListener("click",function(){current="water";refreshActive();});
  btns.wall.addEventListener("click",function(){current="wall";refreshActive();});
  btns.acid.addEventListener("click",function(){current="acid";refreshActive();});
  btns.empty.addEventListener("click",function(){current="empty";refreshActive();});
  refreshActive();
  document.getElementById("clear").addEventListener("click",function(){window.sim.clear();});

  var painting=false;
  var BR=2;
  function paintAt(clientX,clientY){
    var r=canvas.getBoundingClientRect();
    var gx=Math.floor((clientX-r.left)/r.width*W);
    var gy=Math.floor((clientY-r.top)/r.height*H);
    var id=nameToId(current);
    for(var dy=-BR;dy<=BR;dy++){
      for(var dx=-BR;dx<=BR;dx++){
        if(dx*dx+dy*dy>BR*BR+1)continue;
        var nx=gx+dx,ny=gy+dy;
        if(nx<0||nx>=W||ny<0||ny>=H)continue;
        grid[ny*W+nx]=id;
      }
    }
    render();
  }
  canvas.addEventListener("mousedown",function(e){painting=true;paintAt(e.clientX,e.clientY);e.preventDefault();});
  window.addEventListener("mouseup",function(){painting=false;});
  canvas.addEventListener("mousemove",function(e){if(painting)paintAt(e.clientX,e.clientY);});
  canvas.addEventListener("mouseleave",function(){});
  canvas.addEventListener("touchstart",function(e){painting=true;var t=e.touches[0];paintAt(t.clientX,t.clientY);e.preventDefault();},{passive:false});
  canvas.addEventListener("touchmove",function(e){if(painting){var t=e.touches[0];paintAt(t.clientX,t.clientY);}e.preventDefault();},{passive:false});
  canvas.addEventListener("touchend",function(){painting=false;});

  render();
  function loop(){step();render();requestAnimationFrame(loop);}
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
